1	'use client';
2	
3	import {
4	    Anchor,
5	    Button,
6	    Checkbox,
7	    Container,
8	    Group,
9	    Paper,
10	    SegmentedControl,
11	    Stack,
12	    Table,
13	    TableCaption,
14	    TableTbody,
15	    TableTd,
16	    TableTh,
17	    TableThead,
18	    TableTr,
19	    Text,
20	    TextInput,
21	    UnstyledButton,
22	} from '@mantine/core';
23	import { notifications } from '@mantine/notifications';
24	import { IconChevronDown, IconChevronUp, IconSelector } from '@tabler/icons-react';
25	import { useRouter } from 'next/navigation';
26	import { useMemo, useState } from 'react';
27	
28	import {
29	    buildInviteEmail,
30	    comparePlayers,
31	    getImpersonationLabel,
32	    getPreferredEmail,
33	    isOnboarded,
34	    type SortDirection,
35	    type SortKey,
36	} from '@/lib/adminPlayer';
37	import { config } from '@/lib/config';
38	import { formatDate } from '@/lib/dates';
39	import { normalizeEmail } from '@/lib/email/normalizeEmail';
40	import { assertOkResponse, toPublicMessage } from '@/lib/errors';
41	import { captureUnexpectedError } from '@/lib/observability/sentry';
42	import { PlayerDataType } from '@/types';
43	import { AddPlayerInviteProxy } from '@/types/actions/CreatePlayer';
44	import type { SendEmailProxy } from '@/types/actions/SendEmail';
45	
46	type FinishedFilter = 'all' | 'finished' | 'active';
47	type AuthFilter = 'all' | 'invited' | 'claimed';
48	
49	const finishedFilterOptions = [
50	    { label: 'All', value: 'all' },
51	    { label: 'Finished', value: 'finished' },
52	    { label: 'Active', value: 'active' },
53	];
54	
55	const authFilterOptions = [
56	    { label: 'All', value: 'all' },
57	    { label: 'Invited', value: 'invited' },
58	    { label: 'Claimed', value: 'claimed' },
59	];
60	
61	export interface Props {
62	    players: PlayerDataType[];
63	    userEmails?: string[];
64	    userIdByEmail?: Record<string, string>;
65	    onAddPlayerInvite: AddPlayerInviteProxy;
66	    onSendEmail: SendEmailProxy;
67	}
68	
69	/**
70	 * Admin table for managing players, invitations, and email verification.
71	 *
72	 * @param props - Component props.
73	 * @param props.players - Players to render in the table.
74	 * @param props.userEmails - Better Auth user emails to determine onboarding status.
75	 * @returns The rendered admin player list table.
76	 */
77	export const AdminPlayerList = ({
78	    players,
79	    userEmails,
80	    userIdByEmail,
81	    onAddPlayerInvite,
82	    onSendEmail,
83	}: Props) => {
84	    const router = useRouter();
85	    const userEmailSet = useMemo(
86	        () => new Set((userEmails ?? [])
87	            .map((email) => normalizeEmail(email)).filter((email) => email.length > 0)),
88	        [userEmails],
89	    );
90	    const [sortKey, setSortKey] = useState<SortKey>('id');
91	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
92	    const [selectedIds, setSelectedIds] = useState<number[]>([]);
93	    const [filter, setFilter] = useState('');
94	    const [filterFinished, setFilterFinished] = useState<FinishedFilter>('all');
95	    const [filterAuth, setFilterAuth] = useState<AuthFilter>('all');
96	
97	    /**
98	     * Filters players by name and the active tri-state filters.
99	     *
100	     * @returns The filtered player list.
101	     */
102	    const filteredPlayers = useMemo(() => {
103	        if (!players) return [];
104	        const trimmedFilter = filter.trim().toLowerCase();
105	        return players.filter((player) => {
106	            if (trimmedFilter && !player.name?.toLowerCase().includes(trimmedFilter)) return false;
107	            if (filterFinished === 'finished' && !player.finished) return false;
108	            if (filterFinished === 'active' && player.finished) return false;
109	            const claimed = isOnboarded(player, userEmailSet);
110	            if (filterAuth === 'claimed' && !claimed) return false;
111	            if (filterAuth === 'invited' && claimed) return false;
112	            return true;
113	        });
114	    }, [players, filter, filterFinished, filterAuth, userEmailSet]);
115	
116	    /**
117	     * Applies sorting to the filtered players.
118	     *
119	     * @returns The sorted player list.
120	     */
121	    const sortedPlayers = useMemo(() => {
122	        const data = [...filteredPlayers];
123	        data.sort((a, b) => comparePlayers(a, b, sortKey, sortDirection, userEmailSet));
124	        return data;
125	    }, [filteredPlayers, sortKey, sortDirection, userEmailSet]);
126	
127	    if (!players) {
128	        return (
129	            <Text>Loading players...</Text>
130	        );
131	    }
132	
133	    if (players.length === 0) {
134	        return (
135	            <Text>No players found.</Text>
136	        );
137	    }
138	
139	    /**
140	     * Selects or clears all visible players.
141	     *
142	     * @param checked - Whether the select-all checkbox is checked.
143	     */
144	    const toggleSelectAll = (checked: boolean) => {
145	        setSelectedIds(checked ? filteredPlayers.map((player) => player.id) : []);
146	    };
147	
148	    /**
149	     * Toggles a single player row selection.
150	     *
151	     * @param playerId - The player ID to toggle.
152	     * @param checked - Whether the checkbox is checked.
153	     */
154	    const toggleSelectPlayer = (playerId: number, checked: boolean) => {
155	        setSelectedIds((prev) => (
156	            checked ?
157	                [...prev, playerId] :
158	                prev.filter((id) => id !== playerId)
159	        ));
160	    };
161	
162	    const allSelected = filteredPlayers.length > 0 && selectedIds.length === filteredPlayers.length;
163	    const someSelected = selectedIds.length > 0 && !allSelected;
164	    const hasSelection = selectedIds.length > 0;
165	    const selectedPlayers = players.filter((player) => selectedIds.includes(player.id));
166	
167	    /**
168	     * Returns the sort icon for the provided column key.
169	     *
170	     * @param key - Column sort key.
171	     * @returns The appropriate sort icon element.
172	     */
173	    const getSortIcon = (key: SortKey) => {
174	        if (key !== sortKey) return <IconSelector size={14} />;
175	        return sortDirection === 'asc' ? <IconChevronUp size={14} /> : <IconChevronDown size={14} />;
176	    };
177	
178	    /**
179	     * Renders a sortable header label with the current sort icon.
180	     *
181	     * @param label - Column display label.
182	     * @param key - Column sort key.
183	     * @returns A sortable header element.
184	     */
185	    const renderSortHeader = (label: string, key: SortKey) => (
186	        <UnstyledButton
187	            type="button"
188	            onClick={() => handleSort(key)}
189	            aria-label={`Sort by ${label}`}
190	        >
191	            <Group gap={6} wrap="nowrap">
192	                <Text span>{label}</Text>
193	                {getSortIcon(key)}
194	            </Group>
195	        </UnstyledButton>
196	    );
197	
198	    /**
199	     * Updates the sort state for the selected column.
200	     *
201	     * @param key - Column sort key.
202	     */
203	    const handleSort = (key: SortKey) => {
204	        if (key === sortKey) {
205	            setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
206	            return;
207	        }
208	        setSortKey(key);
209	        setSortDirection('asc');
210	    };
211	
212	    /**
213	     * Sends onboarding invites and extra email verifications for the selected
214	     * players. Not expected to called with an empty list since the button is
215	     * disabled, but will handle that case anyway.
216	     *
217	     * @param onboardPlayers - The players to onboard.
218	     * @returns A promise that resolves when onboarding emails are handled.
219	     */
220	    const handleOnboardPlayers = async (onboardPlayers: PlayerDataType[]) => {
221	        const id = notifications.show({
222	            loading: true,
223	            title: 'Onboarding players',
224	            message: 'Sending onboarding emails...',
225	            autoClose: false,
226	            withCloseButton: false,
227	        });
228	
229	        try {
230	            let inviteSent = 0;
231	            let inviteSkipped = 0;
232	            for (const player of onboardPlayers) {
233	                const email = getPreferredEmail(player);
234	                if (!email) {
235	                    inviteSkipped += 1;
236	                } else {
237	                    const inviteLink = await onAddPlayerInvite(player.id, email);
238	                    const html = buildInviteEmail(inviteLink);
239	                    const cc = 'footy@toastboy.co.uk';
240	                    await onSendEmail({
241	                        to: email,
242	                        cc,
243	                        subject: 'Welcome to Toastboy FC!',
244	                        html,
245	                    });
246	                    inviteSent += 1;
247	                }
248	            }
249	
250	            notifications.update({
251	                id,
252	                color: 'teal',
253	                title: 'Onboarding sent',
254	                message: [
255	                    `Invites: ${inviteSent} sent`,
256	                    inviteSkipped ? `${inviteSkipped} skipped` : null,
257	                ].filter(Boolean).join('. ') + '.',
258	                loading: false,
259	                autoClose: config.notificationAutoClose,
260	            });
261	        } catch (err) {
262	            captureUnexpectedError(err, {
263	                layer: 'client',
264	                component: 'AdminPlayerList',
265	                action: 'sendOnboarding',
266	                route: '/footy/admin/players',
267	                extra: {
268	                    selectedCount: selectedIds.length,
269	                },
270	            });
271	            notifications.update({
272	                id,
273	                color: 'red',
274	                title: 'Error',
275	                message: toPublicMessage(err, 'Failed to onboard players.'),
276	                loading: false,
277	                autoClose: false,
278	                withCloseButton: true,
279	            });
280	        }
281	    };
282	
283	    const getUserIdForPlayer = (player: PlayerDataType) => {
284	        const email = normalizeEmail(player.accountEmail);
285	        if (!email) return null;
286	        return userIdByEmail?.[email] ?? null;
287	    };
288	
289	    const handleImpersonatePlayer = async (player: PlayerDataType) => {
290	        const userId = getUserIdForPlayer(player);
291	
292	        // The button should be disabled if there's no userId.
293	
294	        const id = notifications.show({
295	            loading: true,
296	            title: 'Starting impersonation',
297	            message: 'Switching session...',
298	            autoClose: false,
299	            withCloseButton: false,
300	        });
301	
302	        try {
303	            const response = await fetch('/api/auth/admin/impersonate-user', {
304	                method: 'POST',
305	                headers: { 'Content-Type': 'application/json' },
306	                body: JSON.stringify({ userId }),
307	            });
308	
309	            await assertOkResponse(response, {
310	                method: 'POST',
311	                fallbackMessage: 'Failed to impersonate user.',
312	            });
313	
314	            router.refresh();
315	            notifications.update({
316	                id,
317	                color: 'teal',
318	                title: 'Impersonation active',
319	                message: `Now impersonating ${getImpersonationLabel(player)}.`,
320	                loading: false,
321	                autoClose: config.notificationAutoClose,
322	            });
323	        } catch (err) {
324	            const message = toPublicMessage(err, 'Failed to impersonate user.');
325	            notifications.update({
326	                id,
327	                color: 'red',
328	                title: 'Error',
329	                message,
330	                loading: false,
331	                autoClose: false,
332	                withCloseButton: true,
333	            });
334	        }
335	    };
336	
337	    const rows = sortedPlayers.map((player: PlayerDataType) => {
338	        const playerHref = `/footy/player/${encodeURIComponent(player.id || '')}`;
339	        const hasAuthAccount = isOnboarded(player, userEmailSet);
340	        const userId = getUserIdForPlayer(player);
341	
342	        return (
343	            <TableTr key={player.id}>
344	                <TableTd w="2.5rem">
345	                    <Checkbox
346	                        checked={selectedIds.includes(player.id)}
347	                        onChange={(event) => toggleSelectPlayer(player.id, event.currentTarget.checked)}
348	                        aria-label={`Select ${player.name ?? ''}`}
349	                    />
350	                </TableTd>
351	                <TableTd w="4rem">
352	                    <Anchor href={playerHref}>{player.id}</Anchor>
353	                </TableTd>
354	                <TableTd>
355	                    <Anchor href={playerHref}>{player.name}</Anchor>
356	                </TableTd>
357	                <TableTd>{formatDate(player.joined)}</TableTd>
358	                <TableTd>{formatDate(player.finished)}</TableTd>
359	                <TableTd>{hasAuthAccount ? 'Yes' : 'No'}</TableTd>
360	                <TableTd>
361	                    <Button
362	                        size="xs"
363	                        variant="light"
364	                        disabled={!userId}
365	                        onClick={() => handleImpersonatePlayer(player)}
366	                    >
367	                        Impersonate
368	                    </Button>
369	                </TableTd>
370	            </TableTr>
371	        );
372	    });
373	
374	    return (
375	        <Container fluid>
376	            <Paper w="100%" p="xl">
377	                <Stack gap="sm">
378	                    <Text fw={700}>
379	                        {sortedPlayers.length} of {players.length} visible, {selectedIds.length} selected
380	                    </Text>
381	                    <Group justify="space-between" align="center" wrap="wrap" mb="md">
382	                        <Group gap="md" wrap="wrap" align="flex-end">
383	                            <TextInput
384	                                label="Name"
385	                                size="xs"
386	                                placeholder="Filter by name"
387	                                value={filter}
388	                                onChange={(event) => setFilter(event.currentTarget.value)}
389	                            />
390	                            <Stack gap={2}>
391	                                <Text id="finished-filter-label" size="xs" fw={500}>Finished</Text>
392	                                <SegmentedControl
393	                                    aria-labelledby="finished-filter-label"
394	                                    size="xs"
395	                                    data={finishedFilterOptions}
396	                                    value={filterFinished}
397	                                    onChange={(value) => setFilterFinished(value as FinishedFilter)}
398	                                />
399	                            </Stack>
400	                            <Stack gap={2}>
401	                                <Text id="auth-filter-label" size="xs" fw={500}>Auth</Text>
402	                                <SegmentedControl
403	                                    aria-labelledby="auth-filter-label"
404	                                    size="xs"
405	                                    data={authFilterOptions}
406	                                    value={filterAuth}
407	                                    onChange={(value) => setFilterAuth(value as AuthFilter)}
408	                                />
409	                            </Stack>
410	                        </Group>
411	                        <Group gap="xs">
412	                            <Button
413	                                size="xs"
414	                                type="button"
415	                                disabled={!hasSelection}
416	                                onClick={() => handleOnboardPlayers(selectedPlayers)}
417	                            >
418	                                Onboard {selectedPlayers.length} player(s)
419	                            </Button>
420	                        </Group>
421	                    </Group>
422	                    <Table.ScrollContainer minWidth="100%" scrollAreaProps={{ type: 'auto' }}>
423	                        <Table
424	                            striped
425	                            highlightOnHover
426	                            withTableBorder
427	                            withColumnBorders
428	                            w="100%"
429	                            layout="fixed"
430	                        >
431	                            <TableCaption>Registered players</TableCaption>
432	                            <TableThead>
433	                                <TableTr>
434	                                    <TableTh w="2.5rem">
435	                                        <Checkbox
436	                                            checked={allSelected}
437	                                            indeterminate={someSelected}
438	                                            onChange={(event) => toggleSelectAll(event.currentTarget.checked)}
439	                                            aria-label="Select all players"
440	                                        />
441	                                    </TableTh>
442	                                    <TableTh
443	                                        w="2rem"
444	                                        aria-sort={sortKey === 'id' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
445	                                    >
446	                                        {renderSortHeader('ID', 'id')}
447	                                    </TableTh>
448	                                    <TableTh
449	                                        w="10rem"
450	                                        aria-sort={sortKey === 'name' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
451	                                    >
452	                                        {renderSortHeader('Name', 'name')}
453	                                    </TableTh>
454	                                    <TableTh
455	                                        w="7rem"
456	                                        aria-sort={sortKey === 'joined' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
457	                                    >
458	                                        {renderSortHeader('Joined', 'joined')}
459	                                    </TableTh>
460	                                    <TableTh
461	                                        w="7rem"
462	                                        aria-sort={sortKey === 'finished' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
463	                                    >
464	                                        {renderSortHeader('Finished', 'finished')}
465	                                    </TableTh>
466	                                    <TableTh
467	                                        w="4rem"
468	                                        aria-sort={sortKey === 'auth' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
469	                                    >
470	                                        {renderSortHeader('Auth', 'auth')}
471	                                    </TableTh>
472	                                    <TableTh w="7rem">Impersonate</TableTh>
473	                                </TableTr>
474	                            </TableThead>
475	                            <TableTbody>{rows}</TableTbody>
476	                        </Table>
477	                    </Table.ScrollContainer>
478	                </Stack>
479	            </Paper>
480	        </Container>
481	    );
482	};
