                                    <Table.Td>
                                        <Anchor href={`/footy/admin/user/${encodeURIComponent(user.email)}`}>
                                            {user.email}
                                        </Anchor>
                                    </Table.Td>
                                    <Table.Td>
                                        <Switch
                                            checked={user.role === 'admin'}
                                            onChange={(event) => toggleAdmin(user.id, event.currentTarget.checked)}
